function Action({action,title,command,initial={},children}:{action:string;title:string;command:Command;initial?:Row;children?:ReactNode}) {
  const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [failed,setFailed]=useState(false)
  async function submit(event:FormEvent<HTMLFormElement>) {
    event.preventDefault();const form=event.currentTarget; const input:Row={...initial,action};const data=new FormData(form)
    for(const [key,value] of data) input[key]=value
    for(const field of Array.from(form.elements)) if(field instanceof HTMLInputElement){if(field.type==='checkbox')input[field.name]=field.checked;if(field.type==='number')input[field.name]=Number(field.value)}
    if(action==='discovery') {input.discovery=Object.fromEntries(DISCOVERY_FIELDS.map(key=>[key,input[key] || '']));for(const key of DISCOVERY_FIELDS) delete input[key]}
    if(action==='refund_payment') { for(const field of ['netPence','grossPence','termsApprovalReference']) if(!input[field]) delete input[field] }
    if(action==='request_withdrawal') {const ids=data.getAll('ledger').map(String);delete input.ledger;if(ids.length) input.ledgerIds=ids;else input.all=true;for(const key of ['invoiceReference','note']) if(!input[key]) delete input[key]}
    if(action==='set_withdrawal_policy') {const min=Number(input.minAmountPence);if(min>0) input.minAmountPence=String(min);else delete input.minAmountPence}
    if(action==='prepare_withdrawal_payout' && !input.invoiceReference) delete input.invoiceReference
    if(action==='set_market') {input.planKeys=['standard-v2','growth-only-v1','bespoke-v1'].filter(k=>input[`plan_${k}`]===true);for(const k of ['standard-v2','growth-only-v1','bespoke-v1']) delete input[`plan_${k}`]}

