      RAISE EXCEPTION 'This transition needs a matching recorded founder decision';
    END IF;
    IF NEW.status = 'approved' AND (NEW.review_by IS DISTINCT FROM decided.review_by OR NEW.approved_at IS NULL) THEN
      RAISE EXCEPTION 'Approval must carry the recorded review date';
    END IF;
  ELSIF NEW.review_by IS DISTINCT FROM OLD.review_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at THEN
    RAISE EXCEPTION 'Approval evidence belongs to approval';
  END IF;
  IF NEW.status = 'published' AND (NEW.published_at IS NULL OR NEW.review_by < (NEW.published_at AT TIME ZONE 'UTC')::date) THEN
    RAISE EXCEPTION 'Content past its review date cannot be published';
  END IF;
  IF NEW.status <> 'published' AND NEW.published_at IS DISTINCT FROM OLD.published_at THEN RAISE EXCEPTION 'Publication evidence belongs to publication'; END IF;
  IF NEW.status = 'superseded' AND NEW.superseded_at IS NULL THEN RAISE EXCEPTION 'Supersession needs a timestamp'; END IF;
  IF NEW.status = 'archived' AND NEW.archived_at IS NULL THEN RAISE EXCEPTION 'Archiving needs a timestamp'; END IF;
  IF NEW.status = 'archived' AND OLD.status = 'published' AND NEW.archive_reason IS NULL THEN RAISE EXCEPTION 'Withdrawing published content needs a recorded reason'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER empower_content_lifecycle_guard BEFORE INSERT OR UPDATE OR DELETE ON empower_content_versions FOR EACH ROW EXECUTE FUNCTION empower_content_lifecycle();

