    {e.related.length > 0 && <p>Related: {e.related.map((r, i) => <span key={r.href}>{i ? ", " : ""}<Link href={r.href}>{r.title}</Link></span>)}</p>}
    <p className="ac-muted">Sources: {e.sources.join(" · ")}</p>
  </details>
}

