      lessonIds[code] = await upsert({ slug: lessonSlug(code), kind: "lesson", cadence: cadenceFor(l.courseCode), title: l.title, body: l.body, fields, sources: l.sources, summary: `Draft imported from ${l.sourceFile}; not approved.` })
    }
