set -euo pipefail
umask 077
cd /var/www/scalesmiths/ScaleSmiths
SRC=$(git rev-parse --short HEAD)
DIR=/var/backups/scalesmiths/pre-empower-$(date -u +%Y%m%dT%H%M%SZ)-$SRC
mkdir -p "$DIR"
node --env-file=.env -e '
const {execFileSync}=require("child_process");
const url=process.env.MIGRATION_DATABASE_URL||process.env.DATABASE_URL;
execFileSync("pg_dump",["-Fc","--no-owner","-f",process.argv[1]+"/postgres.dump","--dbname",url],{stdio:["ignore","ignore","inherit"]});
const {Client}=require("./admin/node_modules/pg");
const c=new Client({connectionString:url});
(async()=>{await c.connect();
const a=await c.query("select id,hash,created_at from drizzle.__drizzle_migrations order by created_at");
const w=await c.query("select id,hash,created_at from drizzle.__drizzle_web_migrations order by created_at");
require("fs").writeFileSync(process.argv[1]+"/admin-journal.json",JSON.stringify({admin:a.rows,web:w.rows},null,1));
console.log("journal admin="+a.rowCount+" web="+w.rowCount);await c.end()})().catch(e=>{console.error(e.message);process.exit(1)})
' "$DIR"
cp scripts/migration-checksums.json "$DIR/"
git rev-parse HEAD > "$DIR/source-commit.txt"
git status --porcelain > "$DIR/git-status.txt"
cp /root/.pm2/dump.pm2 "$DIR/pm2-dump.pm2"
pm2 jlist > "$DIR/pm2-jlist.json" 2>/dev/null
tar -czf "$DIR/nginx-config.tar.gz" -C / etc/nginx 2>/dev/null
pg_restore --list "$DIR/postgres.dump" | grep -c "TABLE DATA" | sed 's/^/table-data-entries=/'
(cd "$DIR" && sha256sum * > SHA256SUMS)
ls -la "$DIR"
echo "BACKUP_DIR=$DIR"

