server {
    listen 80;
    listen [::]:80;
    server_name partners.scalesmiths.co.uk;

    location ^~ /.well-known/acme-challenge/ {
        root /var/www/letsencrypt;
        default_type "text/plain";
    }

    location / {
        return 301 https://$host$request_uri;
    }
}

server {
    listen 443 ssl;
    listen [::]:443 ssl;
    server_name partners.scalesmiths.co.uk;

    ssl_certificate /etc/letsencrypt/live/admin.scalesmiths.co.uk/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/admin.scalesmiths.co.uk/privkey.pem;
    include /etc/letsencrypt/options-ssl-nginx.conf;
    ssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;

    client_max_body_size 20M;

    location ^~ /.well-known/acme-challenge/ {
        root /var/www/letsencrypt;
        default_type "text/plain";
    }

    location / {
        proxy_pass http://127.0.0.1:3201;
        proxy_http_version 1.1;

        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-Host $host;

        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}
EOF
ssh -o ConnectTimeout=20 scalesmiths 'grep -c "listen \[::\]:443\|listen 443" /etc/nginx/sites-enabled/scalesmiths-admin; diff <(cat) /etc/nginx/sites-available/scalesmiths-partners >/dev/null; cat /etc/nginx/sites-available/scalesmiths-partners | grep -n "certbot\|443" | head' < scalesmiths-partners

