export async function issueInvitation(tx: AdminDatabaseTransaction, applicationId: number, founderId: string, agreementVersion: string, operatingCountry = "GB") {
  requirePartnerActivationEnabled()
  const [founder] = await tx.select().from(adminUsers).where(eq(adminUsers.id, founderId)).for("share").limit(1)
  if (!founder?.active || !hasCapability(founder.role, "expansion.manage")) throw new AdminIdentityError("Founder authority is required.", 403, "forbidden")
  if (!Number.isSafeInteger(applicationId) || applicationId < 1 || !agreementVersion.trim() || agreementVersion.length > 120) throw new AdminIdentityError("Application and agreement version are required.")
  const result = await tx.execute(sql`select id, name, email, status, onboarding_confirmations as confirmations from partner_applications where id = ${applicationId} for update`)
  const applicant = result.rows[0] as { id: number; name: string; email: string; status: string; confirmations: Record<string, unknown> } | undefined
  const prerequisites = applicant?.confirmations
  if (!applicant || applicant.status !== "onboarding" || !prerequisites || !["agreement", "legal", "independentStatus", "operations"].every((key) => prerequisites[key] === true)) throw new AdminIdentityError("Record every onboarding confirmation before inviting a partner.", 409, "onboarding_incomplete")
  if (!/^[A-Z]{2}$/.test(operatingCountry)) throw new AdminIdentityError("Use a two-letter ISO country code for the operating market.")
  // International applicants can be reviewed and progressed to onboarding, but are not invited until a founder has approved their operating market.
  await assertOperatingMarketApproved(tx, operatingCountry, "operating_market_not_approved", "This partner's operating market is not approved, so an invitation cannot be issued. The application can still be reviewed.")
  const now = new Date()
  const expiresAt = new Date(now.getTime() + 48 * 60 * 60 * 1000)
  const token = randomBytes(32).toString("base64url")
  const existing = await tx.execute(sql`select p.id,p.user_id,p.invitation_hash,p.activated_at,u.active,u.role,p.invitation_expires_at <= now() as invitation_expired from expansion_partners p join admin_users u on u.id=p.user_id where p.application_id = ${applicationId} for update of p,u`)
  const pending = existing.rows[0]
  if (pending) {
    // Revocation clears the hash. An expired invitation can be renewed, but a
    // revoked or activated identity cannot be silently revived by this command.
    if (pending.active !== false || pending.role !== "independent_partner" || pending.activated_at !== null || !pending.invitation_hash || pending.invitation_expired !== true) throw new AdminIdentityError("An invitation already exists or this partner requires explicit founder review.", 409, "invitation_exists")
    const partnerId = String(pending.id)
"use client"

import { useState } from "react"
import Link from "next/link"
import { Logo } from "@/components/Logo"

export default function PartnerActivationPage() {
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState("")
  const [activated, setActivated] = useState(false)
  async function activate(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    setBusy(true)
    setError("")
    const form = new FormData(event.currentTarget)
    try {
      // Invitation lives in the URL fragment, never in server access logs or referrers.
      const token = new URLSearchParams(window.location.hash.slice(1)).get("token")
      const response = await fetch("/api/partner/activate", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ token, password: form.get("password") }) })
      const data = await response.json()
      if (!response.ok) throw new Error(data.error || "Activation failed.")
      window.history.replaceState(null, "", "/partner/activate")
      setActivated(true)
    } catch (failure) { setError(failure instanceof Error ? failure.message : "Activation is unavailable.") }
    finally { setBusy(false) }
  }
  return <main className="min-h-screen px-6 py-16 flex items-center justify-center bg-bg text-t1">
    <section className="w-full max-w-md rounded-2xl border border-b1 bg-s1 p-8">
      <Logo size={48} />
      <p className="mt-8 text-xs uppercase tracking-widest text-[#d4b77a]">Independent partner network</p>
      <h1 className="mt-3 text-3xl font-semibold">Your next chapter.</h1>
      {activated ? <div role="status" className="mt-6"><p>Your partner account is active. Sign in with your invited email address and new password.</p><Link href="/login" className="mt-6 inline-block underline text-[#d4b77a]">Continue to sign in</Link></div> : <form onSubmit={activate} className="mt-6 space-y-5">
        <p className="text-t2">Set a secure password to accept your founder-issued invitation. Invitations expire after 48 hours and can be used once.</p>
        <div><label htmlFor="partner-password" className="block mb-2">New password</label><input id="partner-password" name="password" type="password" autoComplete="new-password" minLength={12} maxLength={72} required aria-describedby="password-hint" className="w-full rounded-lg border border-b1 bg-bg px-4 py-3" /><p id="password-hint" className="mt-2 text-sm text-t2">At least 12 characters; maximum 72 UTF-8 bytes.</p></div>
        {error ? <p role="alert" className="text-red-300">{error}</p> : null}
        <button disabled={busy} className="w-full rounded-lg bg-[#d4b77a] px-4 py-3 font-semibold text-black disabled:opacity-60">{busy ? "Activating…" : "Activate partner account"}</button>
      </form>}
    </section>
  </main>
}
