// usage: node register-migration.mjs <owner web|admin> <idx> <tag> <when> <reason>
import { readFileSync, writeFileSync } from "node:fs"
import { createHash } from "node:crypto"
const [owner, idxS, tag, whenS, reason] = process.argv.slice(2)
const idx = Number(idxS), when = Number(whenS)
const dir = owner === "web" ? "web/drizzle" : "admin/drizzle"
const entry = { idx, version: "7", when, tag, breakpoints: true }
const jPath = `${dir}/meta/_journal.json`
const j = JSON.parse(readFileSync(jPath, "utf8"))
if (j.entries.some((e) => e.idx === idx)) throw new Error("exists")
j.entries.push(entry); writeFileSync(jPath, JSON.stringify(j, null, 2) + "\n")
const sql = readFileSync(`${dir}/${tag}.sql`, "utf8")
const sha = createHash("sha256").update(sql).digest("hex")
let c = readFileSync("scripts/migration-checksums.json", "utf8")
const lastMig = c.lastIndexOf('"lifecycle"')
const migEnd = c.indexOf("}", lastMig) + 1
c = c.slice(0, migEnd) + `,\n    {"path":"${dir}/${tag}.sql","sha256":"${sha}","lifecycle":"forward","reason":${JSON.stringify(reason)}}` + c.slice(migEnd)
const jm = c.indexOf(`"path": "${jPath}"`) >= 0 ? c.indexOf(`"path": "${jPath}"`) : c.indexOf(`"path":"${jPath}"`)
const ae = c.indexOf("appendedEntries", jm), close = c.indexOf("]", c.lastIndexOf("}", c.indexOf("]", ae)) )
const arrEnd = c.indexOf("]", ae)
const lastObj = c.lastIndexOf("}", arrEnd) + 1
c = c.slice(0, lastObj) + `,\n        ${JSON.stringify(entry).replace(/,/g, ",")}` + c.slice(lastObj)
writeFileSync("scripts/migration-checksums.json", c)
console.log(owner, tag, sha.slice(0, 12))
EOF
