import "server-only"
import { sql, type SQL } from "drizzle-orm"
import type { AdminDatabaseTransaction } from "@/lib/db"
import { ContentError } from "@/lib/empower-content"
import type { requireCapability } from "./rbac"

/** Operation Empower partner surfaces: their switches and the shared partner guard. Each switch defaults off and is independent. */
type Executor = Pick<AdminDatabaseTransaction, "execute">
type Actor = Awaited<ReturnType<typeof requireCapability>>
export const partnerAcademyEnabled = () => process.env.PARTNER_ACADEMY_ENABLED === "true"
export const partnerResourcesEnabled = () => process.env.PARTNER_RESOURCE_CENTRE_ENABLED === "true"
export const partnerKnowledgeEnabled = () => process.env.PARTNER_KNOWLEDGE_BASE_ENABLED === "true"
const rows = async (tx: Executor, query: SQL) => (await tx.execute(query)).rows as Record<string, unknown>[]
/** Same rule as the rest of the Partner Portal: an activated partner profile, an active user, the partner role and the current session. */
export async function partnerGuard(tx: Executor, actor: Actor) {
  await tx.execute(sql`select id from admin_users where id=${actor.id} for share`)
  const [row] = await rows(tx, sql`select p.id from expansion_partners p join admin_users u on u.id=p.user_id where p.user_id=${actor.id} and p.activated_at is not null
    and u.active=true and u.session_version=${actor.sessionVersion} and u.role::text='independent_partner'`)
  if (!row) throw new ContentError("Active partner profile required.", 403)
  return String(row.id)
}
import { NextResponse } from "next/server"
import { AdminIdentityError } from "@/lib/admin-users"
import { checkLoginRateLimit, getAuthRequestIp, loginRateLimitKeys } from "@/lib/login-limiter"
import { activatePartnerInvitation, requirePartnerActivationEnabled } from "@/lib/server/partner-invitations"

export const dynamic = "force-dynamic"

export async function POST(request: Request) {
  const headers = { "Cache-Control": "private, no-store", "Referrer-Policy": "no-referrer" }
  try {
    const origin = request.headers.get("origin")
    const expectedOrigin = process.env.AUTH_URL ? new URL(process.env.AUTH_URL).origin : new URL(request.url).origin
    if (origin !== expectedOrigin) return NextResponse.json({ error: "Invalid request origin." }, { status: 403, headers })
    requirePartnerActivationEnabled()
    if (!await checkLoginRateLimit(loginRateLimitKeys("partner-activation", getAuthRequestIp(request), ""))) return NextResponse.json({ error: "Too many attempts. Try again later." }, { status: 429, headers })
    if (!request.headers.get("content-type")?.startsWith("application/json")) return NextResponse.json({ error: "JSON is required." }, { status: 415, headers })
    const reader = request.body?.getReader()
    if (!reader) throw new AdminIdentityError("Invalid request.")
    let body = ""
    let size = 0
    const decoder = new TextDecoder()
    while (true) {
      const { done, value } = await reader.read()
      if (done) break
      size += value.byteLength
      if (size > 4096) { await reader.cancel(); return NextResponse.json({ error: "Request is too large." }, { status: 413, headers }) }
      body += decoder.decode(value, { stream: true })
    }
    body += decoder.decode()
    let payload: Record<string, unknown>
    try { payload = JSON.parse(body) } catch { throw new AdminIdentityError("Invalid request.") }
    if (!payload || typeof payload !== "object" || Array.isArray(payload)) throw new AdminIdentityError("Invalid request.")
    await activatePartnerInvitation(payload.token, payload.password)
    return NextResponse.json({ ok: true }, { headers })
  } catch (error) {
    return NextResponse.json({ error: error instanceof AdminIdentityError ? error.safeMessage : "Activation is unavailable. Try again later." }, { status: error instanceof AdminIdentityError ? error.status : 503, headers })
  }
}

