/* Partner activation (Operation Launch Ready). Dark, restrained gold; respects reduced motion. */
.activate{min-height:100dvh;display:flex;align-items:flex-start;justify-content:center;padding:clamp(24px,6vw,72px) 16px;background:radial-gradient(1200px 600px at 50% -10%,#24211a 0%,#121315 55%) #121315;color:#eef0f4;font-family:var(--font-dm),system-ui,sans-serif}
.activate-card{width:100%;max-width:520px;border:1px solid #34353a;background:#18191c;border-radius:16px;padding:clamp(22px,4vw,40px);box-shadow:0 24px 60px -30px #000;animation:activate-in .24s ease-out}
.activate-card-wide{max-width:860px}
.activate-overline{margin:24px 0 8px;font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:#d4b77a}
.activate h1{font-size:clamp(24px,3.4vw,34px);line-height:1.2;letter-spacing:-.02em;margin:10px 0 14px;font-weight:600;outline:none}
.activate p,.activate li{color:#b9bfca;line-height:1.75}
.activate-progress{display:flex;gap:8px;list-style:none;padding:0;margin:8px 0 18px;flex-wrap:wrap}
.activate-progress li{font-size:12px;padding:5px 11px;border-radius:999px;border:1px solid #3a3b41;color:#9aa1ad}
.activate-progress li[data-state=current]{border-color:#d4b77a;color:#f2dfb2;background:#2a251c}
.activate-progress li[data-state=done]{border-color:#3f6b4f;color:#b6e3c5}
.activate-facts{padding-left:20px;margin:0 0 22px}
.activate-meta{font-size:13px}.activate-meta code{font-size:12px;color:#e2cb93}
.activate-document{max-height:min(56vh,560px);overflow:auto;border:1px solid #34353a;border-radius:12px;background:#141517;padding:clamp(16px,3vw,28px);margin:8px 0 22px}
.activate-document:focus-visible{outline:2px solid #d4b77a;outline-offset:3px}
.activate-markdown h3,.activate-markdown h4{color:#f1e2bd;margin:1.4em 0 .5em}.activate-markdown p,.activate-markdown li{color:#cfd3db}
.activate-markdown ul,.activate-markdown ol{padding-left:22px}.activate-markdown ul{list-style:disc}.activate-markdown ol{list-style:decimal}
.activate-end{margin-top:28px;padding-top:12px;border-top:1px dashed #3a3b41;font-size:12px;color:#9aa1ad;text-align:center}
.activate-form fieldset{border:0;padding:0;margin:0;display:grid;gap:8px}
.activate-form fieldset:disabled{opacity:.55}
.activate-form label{font-size:14px;color:#dfe2e8;margin-top:8px}
.activate-form input:not([type=checkbox]){width:100%;min-height:48px;border-radius:10px;border:1px solid #42434a;background:#101113;color:#f2f3f6;padding:10px 14px;font-size:16px}
.activate-form input:focus-visible{outline:2px solid #d4b77a;outline-offset:2px;border-color:#d4b77a}
.activate-check{display:flex;gap:12px;align-items:flex-start;margin:14px 0 6px!important;line-height:1.6}
.activate-check input{width:20px;height:20px;flex:0 0 20px;margin-top:3px;accent-color:#d4b77a}
.activate-hint{font-size:13px;color:#9aa1ad!important;margin:0}
.activate-small{font-size:12px;color:#8f96a2!important;margin-top:18px}
.activate-error{border:1px solid #8a4b44;background:#33211f;color:#f6c1b9!important;border-radius:10px;padding:12px 14px;margin:10px 0}
.activate-button{display:inline-flex;align-items:center;justify-content:center;width:100%;min-height:50px;margin-top:14px;border-radius:10px;border:1px solid #d4b77a;background:linear-gradient(180deg,#e6cf98,#c9aa67);color:#151515;font-weight:650;font-size:15px;cursor:pointer;text-decoration:none;transition:filter .15s ease,transform .08s ease,box-shadow .15s ease}
.activate-button:hover:not(:disabled){filter:brightness(1.06);box-shadow:0 8px 24px -12px #d4b77a}
.activate-button:active:not(:disabled){transform:translateY(1px)}
.activate-button:disabled{opacity:.6;cursor:not-allowed}
.activate-button:focus-visible{outline:2px solid #f2dfb2;outline-offset:3px}
.activate .sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}
@keyframes activate-in{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.activate-card{animation:none}.activate-button{transition:none}.activate-button:active:not(:disabled){transform:none}}

