.activate-progress li{font-size:12px;padding:5px 11px;border-radius:999px;border:1px solid #3a3b41;color:#9aa1ad}
.activate-progress li[data-state=current]{border-color:#d4b77a;color:#f2dfb2;background:#2a251c}
.activate-progress li[data-state=done]{border-color:#3f6b4f;color:#b6e3c5}
.activate-facts{padding-left:20px;margin:0 0 22px}
.activate-meta{font-size:13px}.activate-meta code{font-size:12px;color:#e2cb93}
.activate-document{max-height:min(56vh,560px);overflow:auto;border:1px solid #34353a;border-radius:12px;background:#141517;padding:clamp(16px,3vw,28px);margin:8px 0 22px}
.activate-document:focus-visible{outline:2px solid #d4b77a;outline-offset:3px}
