const coreNames=["currentAgreements","assertIssuableAgreement","acceptOnActivation","agreementForInvitation","founderAgreementRegister","reissueAgreement"]
// recordAcceptance is a non-exported async function
const recM=s.match(/\/\*\* Accept inside the caller's transaction[^\n]*\*\/\nasync function recordAcceptance/);const recStart=recM.index;let j=s.indexOf("{",s.indexOf(")",s.indexOf("recordAcceptance(",recStart)+20));let d=0;for(;j<s.length;j++){if(s[j]==="{")d++;else if(s[j]==="}"){d--;if(d===0)break}}
const ranges=[[recStart,j+1],...coreNames.map(cut)].sort((a,b)=>a[0]-b[0])
const pieces=ranges.map(([a,b])=>s.slice(a,b))
let rest=s;for(const [a,b] of [...ranges].reverse()) rest=rest.slice(0,a)+rest.slice(b)
const headerEnd=s.indexOf("const shape = ")
const shapeEnd=s.indexOf("\n",s.indexOf("publishedAt: new Date",headerEnd))+1
const sharedDefs=s.slice(s.indexOf("type Row = Record"),shapeEnd+3)
let core=`import "server-only"

import { randomUUID } from "node:crypto"
import { sql, type SQL } from "drizzle-orm"
import type { AdminDatabaseTransaction } from "@/lib/db"
