 * Operation Launch Ready: partner agreement records, independent of any session. Callers own the transaction and authority:
 * the invitation and activation services, founder commands, and the partner entry points in ./partner-agreements.
 * The database (migration 0095) fixes version, title, SHA-256 and time on every acceptance and refuses anything else.
 */
${sharedDefs.trim()}

${pieces.join("\n\n")}
`
core=core.replace("async function recordAcceptance","export async function recordAcceptance")
fs.writeFileSync("src/lib/server/partner-agreements-core.ts",core)
rest=rest.replace(/import \{ randomUUID \} from "node:crypto"\n/,"").replace(sharedDefs,"")
